<template>
  <Card v-if="userDetails" class="h-fit">
    <CardHeader>
      <CardTitle>User Management</CardTitle>
    </CardHeader>
    <CardContent class="flex flex-col gap-6">
      <LabeledSelect v-model="selectedRole" :items="roles" label="Role" />
      <div class="flex justify-end gap-2">
        <Button
          class="h-10 self-end"
          :disabled="!hasChanges || isUpdatingUser"
          :loading="isUpdatingUser"
          @click="onSaveChanges"
        >
          Save Changes
        </Button>
      </div>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { UserRole } from '~/client';
import { useToast } from '~/components/ui/toast';
import { getUserRole, userRolesItems } from '~/constants/users/userRoles';
import { type GetUserDetailsResponse } from '~/client';

interface Props {
  userDetails: GetUserDetailsResponse;
}

const props = defineProps<Props>();

const { updateUser, isUpdatingUser } = useUpdateUser();

const { toast } = useToast();

const selectedRole = ref<SelectItem<UserRole>>();

const roles = computed<SelectItem<UserRole>[]>(() =>
  userRolesItems.filter((role) => role.value !== 'subcontractor_canvasser')
);

const hasChanges = computed(() => {
  return selectedRole.value?.value !== props.userDetails.role;
});

onMounted(() => {
  if (!props.userDetails) return;

  selectedRole.value = {
    name: getUserRole(props.userDetails.role).name,
    value: props.userDetails.role,
  };
});

async function onSaveChanges() {
  if (!props.userDetails || isUpdatingUser.value || !selectedRole.value?.value) return;

  try {
    await updateUser({
      user_id: props.userDetails.id,
      data: {
        role: selectedRole.value?.value,
      },
    });
    toast({ title: 'Data updated successfully', variant: 'success' });
  } catch (err: any) {
    showToastError(err.message);
  }
}
</script>

<style scoped lang="scss"></style>
