<template>
  <Card>
    <CardHeader>
      <CardTitle>Danger Zone</CardTitle>
    </CardHeader>
    <CardContent>
      <p class="text-accent-foreground leading-7">
        Account status
        <Badge :variant="processedUserStatus.variant" class="w-fit capitalize inline-block">
          {{ processedUserStatus.name }}
        </Badge>
      </p>
    </CardContent>
    <CardFooter class="flex flex-wrap gap-4 justify-end">
      <ConfirmationDialog2
        v-if="userStatus !== 'deleted' && userId !== currentUserId"
        :title="`${userStatus === 'blocked' ? 'Restore' : 'Block'} user?`"
        :description="`Are you sure you want to ${userStatus === 'blocked' ? 'restore' : 'block'} this user?`"
        :confirm-btn-variant="userStatus === 'blocked' ? 'default' : 'destructive'"
        :is-confirm-loading="isBlockUnblockLoading"
        :is-awaited-close="true"
        :confirm="
          async () => {
            await onBlockUser();
          }
        "
      >
        <Button
          :variant="userStatus === 'blocked' ? 'outline' : 'outline-destructive'"
          :disabled="isBlockUnblockLoading"
          class="h-10 px-3"
        >
          {{ userStatus === 'blocked' ? 'Restore User' : 'Block User' }}
        </Button>
      </ConfirmationDialog2>
      <DeleteUserModal v-if="userStatus !== 'deleted'" :user-id="userId" :user-name="userName" />
    </CardFooter>
  </Card>
</template>

<script lang="ts" setup>
import type { UserStatus } from '~/client';
import { getUserStatus } from '~/constants/users/userStatuses';

const { block, isBlockingUser } = useBlockUser();
const { unblock, isUnblockingUser } = useUnblockUser();

interface Props {
  userStatus: UserStatus | null;
  userId: string;
  userName: string;
}

const props = defineProps<Props>();
const { userId: currentUserId } = useUserRole();

async function onBlockUser() {
  if (!props.userId) return;

  try {
    if (props.userStatus !== 'blocked' && !isBlockingUser.value) {
      await block(props.userId);
    } else if (props.userStatus === 'blocked' && !isUnblockingUser.value) {
      await unblock(props.userId);
    }
  } catch (err: any) {
    console.log(`Failed to ${props.userStatus === 'blocked' ? 'unblock' : 'block'} user`, { message: err.message });
  }
}

const processedUserStatus = computed(() => getUserStatus(props.userStatus || 'new'));
const isBlockUnblockLoading = computed(() => isBlockingUser.value || isUnblockingUser.value);
</script>
