import { updateUserField, type UpdateUserFieldResponse, type UserDetailsResponse, type UserUpdateBody } from '~/client';

export const useUpdateUser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: updateUser, asyncStatus } = useMutation({
    mutation: (params: { user_id: string; data: UserUpdateBody }): Promise<UpdateUserFieldResponse> =>
      updateUserField({
        composable: '$fetch',
        body: params.data,
        path: { user_id: params.user_id },
      }),
    onSuccess: (newData, requestData) => {
      queryCache.setQueryData(['user', requestData.user_id], (oldData?: UserDetailsResponse) => {
        return {
          ...oldData!,
          role: newData.role,
        };
      });
    },
  });

  return {
    updateUser,
    isUpdatingUser: computed(() => asyncStatus.value === 'loading'),
  };
});
