import { enableShareableLink, disableShareableLink, type GetShareableLinkCodeResponse } from '~/client';

export const setShareableLinkEnabled = (
  oldData: GetShareableLinkCodeResponse | undefined,
  enabled: boolean
): GetShareableLinkCodeResponse | undefined => (oldData ? { ...oldData, shareable_link_enabled: enabled } : oldData);

export const useToggleProfileShareableLink = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: { userId: string; enabled: boolean }) =>
      data.enabled
        ? enableShareableLink({ composable: '$fetch', path: { user_id: data.userId } })
        : disableShareableLink({ composable: '$fetch', path: { user_id: data.userId } }),
    onMutate: (data) => {
      queryCache.setQueryData(['profile.shareable-link', data.userId], (oldData?: GetShareableLinkCodeResponse) =>
        setShareableLinkEnabled(oldData, data.enabled)
      );
    },
    onSuccess: (_, data) => {
      showToastSuccess(`Profile link ${data.enabled ? 'enabled' : 'disabled'} successfully`);
    },
    onError(error, data) {
      showToastError(error);
      queryCache.setQueryData(['profile.shareable-link', data.userId], (oldData?: GetShareableLinkCodeResponse) =>
        setShareableLinkEnabled(oldData, !data.enabled)
      );
    },
  });

  return {
    toggleProfileShareableLink: mutateAsync,
    isToggleProfileShareableLinkLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
