<template>
  <div class="grid grid-cols-3 gap-4">
    <div class="col-span-3 xl:col-span-2 flex flex-col gap-4">
      <Card v-if="!userDetails.note && !isNoteDraft && userDetails.role === 'canvasser'">
        <CardHeader>
          <CardTitle>Note</CardTitle>
        </CardHeader>
        <CardContent>
          <p class="text-sm text-muted-foreground">
            No note has been created for this canvasser yet. You can add a note to keep track of important information.
          </p>
        </CardContent>
        <CardFooter>
          <Button variant="outline" :prepend-icon="NotebookPenIcon" @click="isNoteDraft = true">Create a Note</Button>
        </CardFooter>
      </Card>
      <UserDetailsNote
        v-if="(userDetails.note || isNoteDraft) && userDetails.role === 'canvasser'"
        :note="userDetails.note || { content: '', updated_at: Date(), updated_by: null }"
        :is-note-draft="isNoteDraft"
        :user-id="userDetails.id"
        :change-note-draft="() => (isNoteDraft = false)"
      />
      <UserDetailsProfile :user-details="userDetails" />
      <UserDetailsInfo :user-details="userDetails" />
      <SubcontractorCompanyCard
        v-if="isSubcontractorCanvasser && userDetails.subcontractor_company_id"
        :subcontractor-company-id="userDetails.subcontractor_company_id"
      />
      <UserDetailsSettings :data="userDetails.settings" />
      <UserReferredBy
        v-if="userDetails.referral_program?.referred_by"
        :data="userDetails.referral_program.referred_by"
      />
      <UserReferrals
        v-if="userDetails.referral_program?.referrals.length"
        :data="userDetails.referral_program.referrals"
      />
    </div>
    <div class="flex flex-col gap-4 col-span-3 xl:col-span-1">
      <UserDetailsManagement v-if="!isSubcontractorCanvasser" :user-details="userDetails" />
      <UserDetailsDangerZone
        :user-id="userDetails.id"
        :user-status="userDetails.status"
        :user-name="username(userDetails)"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { NotebookPenIcon } from 'lucide-vue-next';
import type { GetUserDetailsResponse } from '~/client';

definePageMeta({
  backGroup: 'user-details',
  backLabel: 'user',
});

const props = defineProps<{
  userDetails: NonNullable<GetUserDetailsResponse>;
}>();

const isNoteDraft = ref(false);

const isSubcontractorCanvasser = computed(() => props.userDetails.role === 'subcontractor_canvasser');
</script>
