<template>
  <EntityNote
    :note="note"
    :is-note-draft="isNoteDraft"
    :change-note-draft="changeNoteDraft"
    :update-note="onUpdate"
    :remove-note="onRemove"
    :is-update-loading="isNoteEditLoading"
    :is-remove-loading="isUserNoteRemoveLoading"
  />
</template>

<script setup lang="ts">
import type { Note } from '~/client';
import { useUserNoteEdit } from '~/mutations/users/notes/edit';
import { useUserNoteRemove } from '~/mutations/users/notes/remove';

const props = defineProps<{
  userId: string;
  note: Note;
  isNoteDraft: boolean;
  changeNoteDraft: () => void;
}>();

const { userNoteEdit, isNoteEditLoading } = useUserNoteEdit();
const { userNoteRemove, isUserNoteRemoveLoading } = useUserNoteRemove();

async function onUpdate(content: string) {
  await userNoteEdit({ userId: props.userId, form: { content } });
}

async function onRemove() {
  await userNoteRemove({ userId: props.userId });
}
</script>
