import { blockUser, type BlockUserResponse, type UserDetailsResponse } from '~/client';

export const useBlockUser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: block, asyncStatus } = useMutation({
    mutation: (user_id: string): Promise<BlockUserResponse> => blockUser({ composable: '$fetch', path: { user_id } }),
    onSuccess: (newData, user_id) => {
      queryCache.setQueryData(['user', user_id], (oldData?: UserDetailsResponse) => {
        return {
          ...oldData!,
          status: newData.new_status,
        };
      });
    },
    onError: (error) => {
      console.error('Failed to block user:', error);
      showToastError('Failed to block user. Please try again.');
    },
  });

  return {
    block,
    isBlockingUser: computed(() => asyncStatus.value === 'loading'),
  };
});
