import { editUserNote, type UserNoteEditRequest, type UserNoteEditResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useUserNoteEdit = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: userNoteEditMutation, asyncStatus } = useMutation({
    mutation: (vars: { userId: string; form: UserNoteEditRequest }): Promise<UserNoteEditResponse> =>
      editUserNote({
        composable: '$fetch',
        path: { user_id: vars.userId },
        body: vars.form,
      }),
    onSuccess: async (newData, { userId }) => {
      showToastSuccess('Note edited successfully');
      await queryCache.invalidateQueries({ key: ['user', userId], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    userNoteEdit: userNoteEditMutation,
    isNoteEditLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
