import {
  generateShareableLink,
  type GenerateShareableLinkResponse2,
  type GetShareableLinkCodeResponse,
} from '~/client';

// Merge the new url into the cached shared-code query so the dialog shows the rotated
// link immediately (shareable_link_enabled is preserved from oldData).
export const mergeRegeneratedShareableLink = (
  oldData: GetShareableLinkCodeResponse | undefined,
  response: GenerateShareableLinkResponse2
): GetShareableLinkCodeResponse | undefined => (oldData ? { ...oldData, ...response } : oldData);

export const useRegenerateProfileShareableLink = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: { userId: string }): Promise<GenerateShareableLinkResponse2> =>
      generateShareableLink({ composable: '$fetch', path: { user_id: data.userId } }),
    onSuccess: (response, data) => {
      queryCache.setQueryData(['profile.shareable-link', data.userId], (oldData?: GetShareableLinkCodeResponse) =>
        mergeRegeneratedShareableLink(oldData, response)
      );
      showToastSuccess('Profile link regenerated successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    regenerateProfileShareableLink: mutateAsync,
    isRegenerateProfileShareableLinkLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
