<template>
  <Dialog v-model:open="isOpen">
    <DialogTrigger as-child>
      <slot>
        <Button variant="outline" :prepend-icon="Share2Icon">Share</Button>
      </slot>
    </DialogTrigger>

    <DialogContent class="sm:max-w-[425px]">
      <template v-if="view === 'regenerate'">
        <DialogHeader>
          <DialogTitle>Regenerate profile link?</DialogTitle>
          <DialogDescription>
            The current public link will stop working. Anyone who has it will no longer be able to view this profile.
          </DialogDescription>
        </DialogHeader>
        <DialogFooter>
          <div class="flex flex-wrap justify-end gap-2">
            <Button variant="outline" class="h-10 px-4" @click="view = 'main'">Cancel</Button>
            <Button
              variant="destructive"
              class="h-10 px-4"
              :loading="isRegenerateProfileShareableLinkLoading"
              @click="onRegenerate"
            >
              Regenerate
            </Button>
          </div>
        </DialogFooter>
      </template>

      <template v-else>
        <DialogHeader>
          <DialogTitle>Share profile</DialogTitle>
          <DialogDescription v-if="!isLoading">This profile is publicly available via this link</DialogDescription>
        </DialogHeader>
        <div class="flex flex-col gap-2">
          <AppLoader v-if="isLoading" variant="inline" subject="profile link" />
          <AppError
            v-else-if="error"
            variant="table"
            :error="error"
            title="Failed to load profile link"
            action-text="Retry"
            :action="refetch"
          />
          <template v-else>
            <div class="flex items-center gap-2">
              <Switch
                id="profile-share-enabled"
                v-model="isLinkEnabled"
                @update:model-value="
                  async (value) => {
                    await toggleProfileShareableLink({ userId: props.userId, enabled: value });
                  }
                "
              >
                <template #thumb>
                  <Spinner v-if="isToggleProfileShareableLinkLoading" class="w-5 h-5 fill-foreground" />
                </template>
              </Switch>
              <Label v-if="!isToggleProfileShareableLinkLoading" for="profile-share-enabled"
                >Link {{ isLinkEnabled ? 'Enabled' : 'Disabled' }}</Label
              >
              <template v-else>
                <Label v-if="isLinkEnabled">Disabling link</Label>
                <Label v-else>Enabling link</Label>
              </template>
            </div>
            <div class="flex flex-row gap-2">
              <div class="relative w-full max-w-sm items-center">
                <span class="absolute start-0 inset-y-0 flex items-center justify-center px-2">
                  <EarthIcon class="size-6 text-muted-foreground" />
                </span>
                <Input
                  id="profile-public-link"
                  type="text"
                  placeholder="Public link"
                  class="pl-10"
                  :model-value="publicUrl"
                />
              </div>
              <CopyButton :value="publicUrl" :disabled="!isLinkEnabled" />
            </div>
            <Button
              variant="outline"
              class="w-full"
              :prepend-icon="RefreshCwIcon"
              :disabled="!isLinkEnabled"
              @click="view = 'regenerate'"
              >Regenerate link</Button
            >
          </template>
        </div>
      </template>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import { EarthIcon, Share2Icon, RefreshCwIcon } from 'lucide-vue-next';
import { Spinner } from '~/assets/icons';
import { getShareableLinkCode } from '~/client';
import { useToggleProfileShareableLink } from '~/mutations/profile/shareable_link/toggle';
import { useRegenerateProfileShareableLink } from '~/mutations/profile/shareable_link/regenerate';

interface Props {
  userId: string;
}

const props = defineProps<Props>();

const isOpen = ref(false);
const view = ref<'main' | 'regenerate'>('main');

watch(isOpen, (open) => {
  if (!open) view.value = 'main';
});

const {
  data: linkData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['profile.shareable-link', props.userId],
  query: () => getShareableLinkCode({ composable: '$fetch', path: { user_id: props.userId } }),
  enabled: () => !!props.userId && isOpen.value,
});

const publicUrl = computed(() => linkData.value?.url);

const { toggleProfileShareableLink, isToggleProfileShareableLinkLoading } = useToggleProfileShareableLink();
const { regenerateProfileShareableLink, isRegenerateProfileShareableLinkLoading } = useRegenerateProfileShareableLink();

const isLinkEnabled = computed({
  get() {
    return linkData.value?.shareable_link_enabled ?? false;
  },
  set() {},
});

async function onRegenerate() {
  await regenerateProfileShareableLink({ userId: props.userId });
  view.value = 'main';
}
</script>
