<template>
  <Card>
    <CardHeader>
      <div class="flex flex-wrap items-center justify-between gap-2">
        <CardTitle>Profile</CardTitle>
        <div class="flex flex-wrap items-center gap-2">
          <ProfileShareDialog v-if="canShareProfile" :user-id="userDetails.id" />
          <NuxtLink v-if="canManageProfile" :to="{ name: 'users-id-edit-profile', params: { id: userDetails.id } }">
            <Button variant="outline" :prepend-icon="PencilIcon">Edit</Button>
          </NuxtLink>
          <ConfirmationDialog2
            v-if="canManageProfile"
            title="Are you sure you want to clear profile data for this user?"
            description="This action cannot be undone. The user will be able to provide their profile information again."
            confirm-btn-text="Clear"
            is-awaited-close
            :confirm="onClearProfile"
            :is-confirm-loading="isRemovingCanvasserInfo"
          >
            <Button variant="outline" :prepend-icon="Trash">Clear</Button>
          </ConfirmationDialog2>
        </div>
      </div>
    </CardHeader>
    <CardContent>
      <ProfileBioDisplay
        :bio="profile?.bio ?? null"
        :profile-picture-url="profile?.profile_picture_url ?? null"
        :profile-picture-original-url="profile?.profile_picture_original_url ?? null"
        :full-name="`${userDetails.first_name} ${userDetails.last_name}`.trim()"
        :role="userDetails.role"
        :city="userDetails.canvasser_general_info?.city ?? null"
        :state="userDetails.canvasser_general_info?.state ?? null"
        :joined-at="userDetails.created_at"
        empty-message="User did not provide profile information yet"
      />
      <EntityAuditInfo :audit="userDetails.canvasser_profile_audit" />
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import { Trash, PencilIcon } from 'lucide-vue-next';
import type { UserDetailsResponse } from '~/client';
import { useRemoveCanvasserInto } from '~/mutations/users/removeCanvasserInfo';
import { canAdminManageProfile } from '~/utils/profileEditPermissions';

const props = defineProps({
  userDetails: {
    type: Object as PropType<UserDetailsResponse>,
    required: true,
  },
});

const profile = computed(() => props.userDetails.canvasser_profile);
const hasProfile = computed(() => Boolean(profile.value?.bio || profile.value?.profile_picture_url));

const { isAdmin, userId } = useUserRole();

const isOwnProfile = computed(() => userId.value === props.userDetails.id);
const canManageProfile = computed(
  () => isAdmin.value && hasProfile.value && canAdminManageProfile(props.userDetails.role, isOwnProfile.value)
);
const canShareProfile = computed(() => isAdmin.value);
const { removeCanvasserInfo, isRemovingCanvasserInfo } = useRemoveCanvasserInto();

async function onClearProfile() {
  await removeCanvasserInfo({ userId: props.userDetails.id, section: 'profile' });
}
</script>

<style scoped lang="scss"></style>
