<template>
  <Card>
    <CardHeader>
      <CardTitle>User Information</CardTitle>
    </CardHeader>
    <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
      <LabeledValue v-for="(item, index) in userInfo" :key="index" :label="item.title">{{ item.value }}</LabeledValue>
    </CardContent>
  </Card>
</template>

<script setup lang="ts">
import type { UserDetailsResponse } from '~/client';
import { getUserRole } from '~/constants/users/userRoles';

type ValueOf<T> = T[keyof T];

interface UserInfoItem {
  title: string;
  value: ValueOf<UserDetailsResponse>;
}

const props = defineProps({
  userDetails: {
    type: Object as PropType<UserDetailsResponse>,
    required: true,
  },
});

const userInfo = computed<UserInfoItem[]>(() => {
  return [
    {
      title: 'Full Name',
      value: props.userDetails.first_name + ' ' + props.userDetails.last_name,
    },
    {
      title: 'Email',
      value: props.userDetails.email,
    },
    {
      title: 'Phone',
      value: props.userDetails.phone,
    },
    {
      title: 'Role',
      value: getUserRole(props.userDetails.role).name,
    },
  ];
});
</script>

<style scoped lang="scss"></style>
