import { removeUserNote, type UserNoteRemoveResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useUserNoteRemove = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (vars: { userId: string }): Promise<UserNoteRemoveResponse> =>
      removeUserNote({
        composable: '$fetch',
        path: { user_id: vars.userId },
      }),
    onSuccess: async (newData, { userId }) => {
      showToastSuccess('Note removed successfully');
      await queryCache.invalidateQueries({ key: ['user', userId], exact: true });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    userNoteRemove: mutateAsync,
    isUserNoteRemoveLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
