import { unblockUser, type UnblockUserResponse, type UserDetailsResponse } from '~/client';

export const useUnblockUser = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: unblock, asyncStatus } = useMutation({
    mutation: (user_id: string): Promise<UnblockUserResponse> =>
      unblockUser({ composable: '$fetch', path: { user_id } }),
    onSuccess: (newData, user_id) => {
      queryCache.setQueryData(['user', user_id], (oldData?: UserDetailsResponse) => {
        return {
          ...oldData!,
          status: newData.new_status,
        };
      });
    },
    onError: (error) => {
      console.error('Failed to unblock user:', error);
      showToastError('Failed to unblock user. Please try again.');
    },
  });

  return {
    unblock,
    isUnblockingUser: computed(() => asyncStatus.value === 'loading'),
  };
});
